                meaningBn = "হে আল্লাহ! আমি আপনার নিকট প্রার্থনা করছি এই ওসিলায় যে, সমস্ত প্রশংসা কেবলমাত্র আপনারই। আপনি ছাড়া কোনো সত্য উপাস্য নেই, আপনি পরম অনুগ্রহকারী, আপনি আসমান ও জমিনের অভূতপূর্ব স্রষ্টা। হে মহিমাময় ও মহানুভবতার অধিকারী! হে চিরঞ্জীব ও সবকিছুর নিয়ন্ত্রক!",
                fojilotBn = "হযরত আনাস (রা.) বর্ণনা করেন: নবীজী ﷺ এক সাহাবীকে সালাতে এ দো‘আ পড়তে শুনে বললেন:\n‘সে আল্লাহকে তাঁর ইসমে আজম দিয়ে ডেকেছে, যা দ্বারা ডাকলে তিনি সাড়া দেন এবং যা দ্বারা চাইলে তিনি দান করেন।’ (তিরমিযী: ৩৫৪৪, নাসাঈ: ১৩০০, সহীহ ইবনে হিব্বান: ৮৯৩)।",
                detailsBn = "আবু দাউদ, নাসাঈ, আহমাদ, বুখারীর আল-আদাবুল মুফরাদ ও ত্বাবারানীতে একাধিক সহীহ সূত্রে এ হাদীসটি বর্ণিত হয়েছে। এটি অন্যতম সর্বাধিক প্রচলিত ও পরিপূর্ণ ইসমে আজম।",
                referenceBn = "সুনান আবু দাউদ: ১৪৯৫; জামে আত-তিরমিযী: ৩৫৪৪; সুনান আন-নাসাঈ: ১৩০০; সহীহ ইবনে হিব্বান: ৮৯৩; আল-আদাবুল মুফরাদ"
