            // ৬. ৩. ইসমে আজম কিভাবে পড়তে হবে ও কখন পড়তে হয়? (How & When to Pray Isme Azam)
            IslamicLifeCardItem(
                id = "ia_how_and_when_to_read",
                serialNumberBn = "৬",
                repetitionOrTimeBn = "আমলের ৪টি ধাপ ও ৫টি শ্রেষ্ঠ সময়",
                titleBn = "৩. ইসমে আজম কিভাবে পড়তে হবে ও কখন পড়তে হয়? (আমলের সঠিক নিয়ম)",
                arabicText = "اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ ۝ اللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنَّ لَكَ الْحَمْدَ ۝ يَا ذَا الْجَلَالِ وَالإِكْرَامِ يَا حَيُّ يَا قَيُّومُ",
                pronunciationBn = "আল্লা-হুম্মা সাল্লি ‘আলা- মুহাম্মাদ... আল্লা-হুম্মা ইন্নী আস-আলুকা বি-আন্না লাকাল হামদু... ইয়া যাল জালা-লি ওয়াল ইকরাম, ইয়া হাইয়্যু ইয়া ক্বাইয়্যূম।",
                meaningBn = "আলেমদের পরামর্শ অনুযায়ী আমল করার সঠিক ৪টি ধাপ:\n\n১. পবিত্রতা ও দুরুদ শরীফ পাঠ:\nওজু অবস্থায় কিবলামুখী হয়ে প্রথমে আল্লাহর হামদ বা প্রশংসা এবং নবীজী ﷺ-এর ওপর যেকোনো দুরুদ শরীফ (যেমন: দুরুদে ইব্রাহিম) পাঠ করুন।\n\n২. ইসমে আজমের দোয়া পাঠ:\nহাদিসে বর্ণিত যেকোনো একটি ইসমে আজম দোয়া (যেমন: বুরাইদা রা. বর্ণিত দোয়া কিংবা 'ইয়া হাইয়ু ইয়া কাইয়ুম') অত্যন্ত বিনম্র কণ্ঠে ১ বার, ৩ বার, ৭ বার বা ১১ বার পাঠ করুন।\n\n৩. মনের আকুতি জানিয়ে দোয়া চাওয়া:\nইসমে আজম পাঠের ঠিক পর পরই আপনার মনের সমস্ত নেক ইচ্ছা, রোগমুক্তি, ঋণমুক্তি বা বিপদ দূর করার জন্য কায়মনোবাক্যে আল্লাহর দরবারে দু'হাত তুলে মোনাজাত করুন।\n\n৪. দোয়া কবুলের শ্রেষ্ঠ সময়ে পাঠ করা (Best Timing):\nযেকোনো সময় ইসমে আজম পড়া যায়। তবে বিশেষ করে—\n(ক) ফরজ নামাজের পর ও সালাম ফেরানোর পূর্বে শেষ বৈঠকে,\n(খ) রাতের শেষ তৃতীয়াংশে তাহাজ্জুদ নামাজের পর,\n(গ) সেজদারত অবস্থায়,\n(ঘ) আজান ও ইকামতের মধ্যবর্তী সময়ে এবং\n(ঙ) জুমার দিন আসরের পর সূর্যাস্তের আগমুহূর্তে ইসমে আজম পড়ে দোয়া করা সর্বাধিক কার্যকরী।",
                fojilotBn = "রাসূলুল্লাহ ﷺ বলেছেন: ‘যে ব্যক্তি ইসমে আজম দিয়ে দোয়া করে তার দোয়া আল্লাহ অবশ্যই কবুল করেন।’ (মুসনাদে আহমদ: ১২২০৫)। শেষ বৈঠকে সালামের আগে পাঠ করা সুন্নাত দ্বারা প্রমাণিত সবচেয়ে শক্তিশালী মুহূর্ত।",
                detailsBn = "ইসমে আজম পাঠ শেষে নবীজী ﷺ-এর ওপর পুনরায় দুরুদ পাঠ করে দো‘আ শেষ করা সুন্নাহসম্মত আদব।",
                referenceBn = "সহীহ মুসলিম: ৪০৭; জামে আত-তিরমিযী: ৩৫৪৪; মুসনাদে আহমাদ: ১২২০৫; সুনান আবু দাঊদ: ১৪৯৫"
            ),

