                titleBn = "৪. দোয়া কবুল হওয়ার আবশ্যকীয় শর্তসমূহ (আমল কবুলের নীতিমালা)",
                arabicText = "ادْعُوا اللَّهَ وَأَنْتُمْ مُوقِنُونَ بِالْإِجَابَةِ، وَاعْلَمُوا أَنَّ اللَّهَ لَا يَسْتَجِيبُ دُعَاءً مِنْ قَلْبٍ غَافِلٍ لَاهٍ",
                pronunciationBn = "উদ্‌‘উল্লা-হা ওয়া আনতুম মূক্বিনূনা বিল ইজা-বাহ, ওয়া’লামূ আন্নাল্লা-হা লা- ইয়াস্তাজীবু দু‘আ-আম মিন ক্বালবিন গা-ফিলিন লা-হিন।",
                meaningBn = "মনে রাখা আবশ্যক, ইসমে আজম কোনো তান্ত্রিক জাদুমন্ত্র নয় যে কেবল মুখ দিয়ে আওড়ালেই অলৌকিক কিছু ঘটবে। বরং হাদিস অনুযায়ী দোয়া কবুলের জন্য নিম্নোক্ত শর্তগুলো পূরণ হতে হবে:\n\n১. হালাল রুজি ও খাবার:\nরাসুলুল্লাহ ﷺ বলেছেন, এক ব্যক্তি দীর্ঘ সফর করে এলোমেলো চুলে আকাশের দিকে হাত তুলে ডাকে 'হে রব! হে রব!', অথচ তার খাদ্য হারাম, পানীয় হারাম, পোশাক হারাম এবং সে হারাম দ্বারাই পুষ্ট— কীভাবে তার দোয়া কবুল হতে পারে? (সহীহ মুসলিম: ১০১৫)।\n\n২. অন্তরের একাগ্রতা ও দৃঢ় বিশ্বাস:\nরাসুলুল্লাহ ﷺ ইরশাদ করেছেন: ‘তোমরা কবুল হওয়ার পূর্ণ দৃঢ় বিশ্বাস নিয়ে আল্লাহর কাছে দোয়া করো। আর জেনে রাখো, নিশ্চয়ই আল্লাহ কোনো উদাসীন ও অসচেতন অন্তরের দোয়া কবুল করেন না।’ (জামে আত-তিরমিযী: ৩৪৭৯)।\n\n৩. তড়িঘড়ি ও নিরাশ না হওয়া:\n‘দোয়া করলাম অথচ ফল পেলাম না’— এমন ভেবে নিরাশ হয়ে দোয়া ত্যাগ করা যাবে না। আল্লাহ বান্দার সবচেয়ে উপযুক্ত ও কল্যাণকর সময়ে প্রতিদান দেন (সহীহ বুখারী: ৬৩৪০)।\n\n৪. কোনো পাপ বা আত্মীয়তার সম্পর্কচ্ছেদের দোয়া না করা:\nকেবলমাত্র ন্যায়সঙ্গত, কল্যাণকর ও তাকওয়াপূর্ণ বিষয়ে দোয়া করতে হবে (সহীহ মুসলিম: ২৭৩৫)।",
                fojilotBn = "এই ৪টি শর্ত পূরণ করে বান্দা যখন ইসমে আজমের উসিলায় আল্লাহর কাছে কিছু যাচ্ঞা করে, আল্লাহ তাআলা হয় তৎক্ষণাৎ তা দান করেন, নতুবা তার পরিবর্তে কোনো বিপদ দূর করে দেন, অথবা পরকালের জন্য মহা প্রতিদান হিসেবে জমা রাখেন।",
                detailsBn = "হালাল খাদ্য গ্রহণ ও আন্তরিক বিনয় হলো সকল দো‘আ আসমানে পৌঁছার মূল ভিত্তি।",
                referenceBn = "সহীহ মুসলিম: ১০১৫, ২৭৩৫; সহীহ বুখারী: ৬৩৪০; জামে আত-তিরমিযী: ৩৪৭৯"
            ),

